// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address recipient) public {
        vm.assume(amount > 0);
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        uint256 balanceAfter = address(c).balance;
        assertTrue(!ok || balanceAfter == balanceBefore - amount);
    }
}
